<?php
namespace App\Services;
use App\Core\Database;
final class MetadataService {
    public static function get(int $tenantId,string $entity,int $id):array{$db=Database::connection();$f=$db->prepare("SELECT f.*,v.value_text FROM custom_fields f LEFT JOIN custom_field_values v ON v.custom_field_id=f.id AND v.tenant_id=f.tenant_id AND v.entity_id=? WHERE f.tenant_id=? AND f.entity_type=? ORDER BY f.id");$f->execute([$id,$tenantId,$entity]);$t=$db->prepare("SELECT t.id,t.name FROM entity_tags et JOIN tags t ON t.id=et.tag_id AND t.tenant_id=et.tenant_id WHERE et.tenant_id=? AND et.entity_type=? AND et.entity_id=? ORDER BY t.name");$t->execute([$tenantId,$entity,$id]);$all=$db->prepare("SELECT id,name FROM tags WHERE tenant_id=? ORDER BY name");$all->execute([$tenantId]);return['fields'=>$f->fetchAll(),'tags'=>$t->fetchAll(),'all_tags'=>$all->fetchAll()];}
    public static function save(int $tenantId,string $entity,int $id,array $values,array $tagIds):void{$db=Database::connection();$db->beginTransaction();try{$valid=$db->prepare("SELECT id FROM custom_fields WHERE tenant_id=? AND entity_type=?");$valid->execute([$tenantId,$entity]);$ids=array_map('intval',$valid->fetchAll(\PDO::FETCH_COLUMN));$up=$db->prepare("INSERT INTO custom_field_values(tenant_id,custom_field_id,entity_id,value_text) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE value_text=VALUES(value_text)");foreach($values as $fid=>$value){$fid=(int)$fid;if(in_array($fid,$ids,true))$up->execute([$tenantId,$fid,$id,is_array($value)?json_encode($value):$value]);}$db->prepare("DELETE FROM entity_tags WHERE tenant_id=? AND entity_type=? AND entity_id=?")->execute([$tenantId,$entity,$id]);$check=$db->prepare("SELECT id FROM tags WHERE tenant_id=? AND id=?");$ins=$db->prepare("INSERT IGNORE INTO entity_tags(tenant_id,tag_id,entity_type,entity_id) VALUES(?,?,?,?)");foreach(array_unique(array_map('intval',$tagIds)) as $tag){$check->execute([$tenantId,$tag]);if($check->fetchColumn())$ins->execute([$tenantId,$tag,$entity,$id]);}$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
}
